433→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
434→	t.Helper()
435→	path := filepath.Join(dir, ".entire", "settings.json")
436→	data, err := os.ReadFile(path)
437→	if err != nil {
438→		t.Fatalf("read settings: %v", err)
439→	}
440→	var settings map[string]any
441→	if err := json.Unmarshal(data, &settings); err != nil {
442→		t.Fatalf("parse settings: %v", err)
443→	}
444→	for k, v := range extra {
445→		settings[k] = v
446→	}
447→	out, err := json.MarshalIndent(settings, "", "  ")
448→	if err != nil {
