package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
		return
	}
	Register(&CursorCLI{})
}

// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
// The CLI binary is called "agent" and uses Cursor's hooks system via
// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
//
// All E2E interactions use interactive (tmux) mode so that the full hook
// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
type CursorCLI struct{}

func (a *CursorCLI) Name() string               { return "cursor-cli" }
func (a *CursorCLI) Binary() string             { return "agent" }
func (a *CursorCLI) EntireAgent() string        { return "cursor" }
func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }

// PromptPattern returns a regex matching the Cursor CLI's TUI input prompt.
// The CLI shows a styled input box with placeholder text when ready for input.
func (a *CursorCLI) PromptPattern() string { return `/ commands` }

func (a *CursorCLI) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{
		"overloaded",
		"rate limit",
		"429",
		"503",
		"529",
		"ECONNRESET",
		"ETIMEDOUT",
		"server error",
		"Internal Server Error",
	} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (a *CursorCLI) Bootstrap() error {
	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
	}
	return nil
}

func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 90 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}

	displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"

	// Start an interactive tmux session so all hooks fire
	// (beforeSubmitPrompt and stop don't fire in headless -p mode).
	s, err := a.startInteractiveSession(dir)
	if err != nil {
		return Output{Command: displayCmd, ExitCode: -1},
			fmt.Errorf("start interactive session: %w", err)
	}
	defer s.Close()

	// Wait for trust dialog and accept it.
	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
	}

	// Wait for the TUI to be ready.
	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
			fmt.Errorf("waiting for startup prompt: %w", err)
	}

	// Send the prompt.
	if err := s.Send(prompt); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
			fmt.Errorf("sending prompt: %w", err)
	}

	// Wait for the prompt pattern to reappear (agent finished processing).
	content, waitErr := s.WaitFor(a.PromptPattern(), timeout)
	if waitErr != nil {
		// Check for deadline exceeded to allow transient error detection.
		if ctx.Err() == context.DeadlineExceeded {
			waitErr = fmt.Errorf("%w: %w", waitErr, context.DeadlineExceeded)
		}
		return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, waitErr
	}

	return Output{Command: displayCmd, Stdout: content, ExitCode: 0}, nil
}

func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	s, err := a.startInteractiveSession(dir)
	if err != nil {
		return nil, err
	}

	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
		_ = s.Close()
		return nil, err
	}

	// Wait for the TUI to be ready (input prompt).
	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

// startInteractiveSession creates a new tmux session running the Cursor CLI
// in interactive mode (no -p flag) so all hooks fire.
func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
	// Resolve to absolute path so tmux can find the binary even if its
	// shell doesn't inherit the test process's PATH (common on CI).
	bin, err := exec.LookPath(a.Binary())
	if err != nil {
		return nil, fmt.Errorf("agent binary not found: %w", err)
	}

	// Build env-wrapped command so the tmux session inherits critical env vars.
	// tmux starts a new shell that doesn't inherit Go's os.Environ().
	var envArgs []string
	for _, key := range []string{"CURSOR_API_KEY", "PATH", "HOME", "TERM"} {
		if v := os.Getenv(key); v != "" {
			envArgs = append(envArgs, key+"="+v)
		}
	}

	args := append([]string{"env"}, envArgs...)
	args = append(args, bin, "--force", "--workspace", dir)

	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
	unset := []string{"CI"}
	return NewTmuxSession(name, dir, unset, args[0], args[1:]...)
}

// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
// and presses "a" to accept it. The dialog only shows on the first launch in
// a workspace — subsequent sessions in the same directory skip it.
func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
	// Race: either the trust dialog or the input prompt will appear first.
	// Use a short timeout to check for the trust dialog without blocking
	// too long if the workspace is already trusted.
	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 30*time.Second)
	if err != nil {
		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
	}
	if strings.Contains(content, "Trust this workspace") {
		if err := s.SendKeys("a"); err != nil {
			return fmt.Errorf("accepting trust dialog: %w", err)
		}
	}
	return nil
}

package strategy

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// resolveTranscriptPath returns the current path to the session's transcript file.
// If the file exists at state.TranscriptPath, that path is returned immediately.
//
// If the file is missing (os.ErrNotExist), the function re-resolves the path
// using the agent's ResolveSessionFile method. This handles agents that relocate
// transcripts mid-session (e.g., Cursor CLI switching from a flat layout
// <dir>/<id>.jsonl to a nested layout <dir>/<id>/<id>.jsonl).
//
// On successful re-resolution, state.TranscriptPath is updated so that
// subsequent reads use the correct path without repeating the resolution.
func resolveTranscriptPath(state *SessionState) (string, error) {
	if state.TranscriptPath == "" {
		return "", errors.New("no transcript path in session state")
	}

	// Fast path: file exists at the stored location.
	if _, err := os.Stat(state.TranscriptPath); err == nil {
		return state.TranscriptPath, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		// Non-ENOENT error (permission denied, etc.) — return as-is.
		return "", fmt.Errorf("failed to access transcript: %w", err)
	}

	// File not found — attempt re-resolution via the agent.
	ag, agErr := agent.GetByAgentType(state.AgentType)
	if agErr != nil {
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Extract the session dir and agent session ID from the stored path.
	// Stored path format: <sessionDir>/<agentSessionID>.jsonl
	sessionDir := filepath.Dir(state.TranscriptPath)
	base := filepath.Base(state.TranscriptPath)
	agentSessionID := strings.TrimSuffix(base, filepath.Ext(base))

	resolved := ag.ResolveSessionFile(sessionDir, agentSessionID)
	if resolved == state.TranscriptPath {
		// Agent resolved to the same path — file genuinely doesn't exist.
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Check if the re-resolved path exists.
	if _, err := os.Stat(resolved); err != nil {
		return "", fmt.Errorf("transcript not found at %s (also tried %s): %w", state.TranscriptPath, resolved, os.ErrNotExist)
	}

	// Update state so subsequent reads use the correct path.
	state.TranscriptPath = resolved
	return resolved, nil
}

//go:build e2e

package tests

import (
	"context"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/testutil"
)

// TestMultiSessionManualCommit: two prompts create files, user commits manually.
func TestMultiSessionManualCommit(t *testing.T) {
	testutil.ForEachAgent(t, 3*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		_, err := s.RunPrompt(t, ctx, "create a markdown file at docs/red.md with a paragraph about the colour red. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent prompt 1 failed: %v", err)
		}

		_, err = s.RunPrompt(t, ctx, "create a markdown file at docs/blue.md with a paragraph about the colour blue. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent prompt 2 failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add md files about red and blue")

		testutil.AssertFileExists(t, s.Dir, "docs/*.md")
		testutil.AssertNewCommits(t, s, 1)

		testutil.WaitForCheckpoint(t, s, 15*time.Second)
		testutil.AssertCheckpointAdvanced(t, s)

		cpID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID)
		testutil.AssertNoShadowBranches(t, s.Dir)
	})
}

// TestMultiSessionSequential: two prompts each commit separately, distinct checkpoints.
func TestMultiSessionSequential(t *testing.T) {
	testutil.ForEachAgent(t, 3*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		_, err := s.RunPrompt(t, ctx,
			"create a markdown file at docs/red.md about the colour red, then git add and git commit it with a short message. Do not ask for confirmation, just make the change. Do not include any trailers or metadata in the commit message. Do not use worktrees.")
		if err != nil {
			t.Fatalf("agent prompt 1 failed: %v", err)
		}

		_, err = s.RunPrompt(t, ctx,
			"create a markdown file at docs/blue.md about the colour blue, then git add and git commit it with a short message. Do not ask for confirmation, just make the change. Do not include any trailers or metadata in the commit message. Do not use worktrees.")
		if err != nil {
			t.Fatalf("agent prompt 2 failed: %v", err)
		}

		testutil.AssertFileExists(t, s.Dir, "docs/*.md")
		testutil.AssertNewCommits(t, s, 2)

		testutil.WaitForCheckpoint(t, s, 15*time.Second)
		testutil.AssertCheckpointAdvanced(t, s)

		cpID1 := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID1)
		cpID2 := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD~1")
		testutil.AssertCheckpointExists(t, s.Dir, cpID2)

		cpIDs := testutil.CheckpointIDs(t, s.Dir)
		for _, id := range cpIDs {
			testutil.AssertCheckpointHasSingleSession(t, s.Dir, id)
		}
		testutil.AssertDistinctSessions(t, s.Dir, cpIDs)
		testutil.AssertNoShadowBranches(t, s.Dir)
	})
}

