	require.NoError(t, err)
	state.Phase = session.PhaseActive
	state.TurnCheckpointIDs = nil

	// Point transcript to an empty file — this will cause condensation to fail
	// with "live transcript is empty", simulating the Cursor race condition
	// where the agent commits before writing the transcript.
	emptyTranscript := filepath.Join(dir, ".entire", "metadata", sessionID, "empty.jsonl")
	require.NoError(t, os.WriteFile(emptyTranscript, []byte(""), 0o644))
