	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify: IDLE session was NOT condensed (transcript fallback was skipped)
	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
