1555→// extractModifiedFilesFromLiveTranscript extracts modified files from the live transcript
1556→// (including subagent transcripts) starting from the given offset, and normalizes them
1557→// to repo-relative paths. Returns the normalized file list.
1558→//
1559→// Callers must ensure the transcript is prepared (e.g., via prepareTranscriptForState
1560→// or hasNewTranscriptWork) before calling this function.
1561→func (s *ManualCommitStrategy) extractModifiedFilesFromLiveTranscript(ctx context.Context, state *SessionState, offset int) []string {
1562→	logCtx := logging.WithComponent(ctx, "checkpoint")
1563→
1564→	if state.TranscriptPath == "" || state.AgentType == "" {
1565→		return nil
1566→	}
1567→
1568→	// Re-resolve transcript path — handles agents that relocate transcripts mid-session.
1569→	if _, resolveErr := resolveTranscriptPath(state); resolveErr != nil {
1570→		logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: transcript path resolution failed",
1571→			slog.String("session_id", state.SessionID),
1572→			slog.Any("error", resolveErr),
1573→		)
1574→		return nil
1575→	}
1576→
1577→	ag, err := agent.GetByAgentType(state.AgentType)
1578→	if err != nil {
1579→		return nil
1580→	}
1581→
1582→	analyzer, ok := agent.AsTranscriptAnalyzer(ag)
1583→	if !ok {
1584→		return nil
1585→	}
1586→
1587→	var modifiedFiles []string
1588→
1589→	// For Claude Code, use ExtractAllModifiedFiles which parses the main transcript
1590→	// AND subagent transcripts in a single pass, avoiding redundant parsing.
1591→	if state.AgentType == agent.AgentTypeClaudeCode {
1592→		subagentsDir := filepath.Join(filepath.Dir(state.TranscriptPath), state.SessionID, "subagents")
1593→		transcriptData, readErr := os.ReadFile(state.TranscriptPath)
1594→		if readErr != nil {
1595→			logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: failed to read transcript",
1596→				slog.String("session_id", state.SessionID),
1597→				slog.String("error", readErr.Error()),
1598→			)
1599→		} else {
1600→			// TODO: fix when we refactor this area.
1601→			// rather than instantiating claude specifically, we should iterate agents.
1602→			c := &claudecode.ClaudeCodeAgent{}
1603→			allFiles, extractErr := c.ExtractAllModifiedFiles(transcriptData, offset, subagentsDir)
1604→			if extractErr != nil {
1605→				logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: extraction failed",
1606→					slog.String("session_id", state.SessionID),
1607→					slog.String("error", extractErr.Error()),
1608→				)
1609→			} else {
1610→				modifiedFiles = allFiles
1611→			}
1612→		}
1613→	} else {
1614→		files, _, err := analyzer.ExtractModifiedFilesFromOffset(state.TranscriptPath, offset)
1615→		if err != nil {
1616→			logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: main transcript extraction failed",
1617→				slog.String("transcript_path", state.TranscriptPath),
1618→				slog.Any("error", err),
1619→			)
1620→		} else {
1621→			modifiedFiles = files
1622→		}
1623→	}
1624→
1625→	if len(modifiedFiles) == 0 {
1626→		return nil
1627→	}
1628→
1629→	// Normalize to repo-relative paths.
1630→	// Transcript tool_use entries contain absolute paths (e.g., /Users/alex/project/src/main.go)
1631→	// but getStagedFiles/committedFiles use repo-relative paths (e.g., src/main.go).
1632→	basePath := state.WorktreePath
1633→	if basePath == "" {
1634→		if wp, wpErr := paths.WorktreeRoot(ctx); wpErr == nil {
1635→			basePath = wp
1636→		}
1637→	}
1638→	if basePath != "" {
1639→		normalized := make([]string, 0, len(modifiedFiles))
1640→		for _, f := range modifiedFiles {
1641→			if rel := paths.ToRelativePath(f, basePath); rel != "" {
1642→				normalized = append(normalized, rel)
1643→			} else {
1644→				normalized = append(normalized, f)
1645→			}
1646→		}
1647→		modifiedFiles = normalized
1648→	}
1649→
1650→	return modifiedFiles
1651→}
