1653→// addTrailerForAgentCommit handles the fast path when an agent is committing
1654→// (ACTIVE session + no TTY). Generates a checkpoint ID and adds the trailer
1655→// directly, bypassing content detection and interactive prompts.
1656→func (s *ManualCommitStrategy) addTrailerForAgentCommit(logCtx context.Context, commitMsgFile string, state *SessionState, source string) error {
1657→	cpID, err := id.Generate()
1658→	if err != nil {
1659→		return nil //nolint:nilerr // Hook must be silent on failure
1660→	}
1661→
1662→	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
1663→	if err != nil {
1664→		return nil //nolint:nilerr // Hook must be silent on failure
1665→	}
1666→
1667→	message := string(content)
1668→
1669→	// Don't add if trailer already exists
1670→	if _, found := trailers.ParseCheckpoint(message); found {
