1678→		slog.String("source", source),
1679→		slog.String("checkpoint_id", cpID.String()),
1680→		slog.String("session_id", state.SessionID),
1681→	)
1682→
1683→	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
1684→		return nil //nolint:nilerr // Hook must be silent on failure
1685→	}
