1689→// addCheckpointTrailer adds the Entire-Checkpoint trailer to a commit message.
1690→// Handles proper trailer formatting (blank line before trailers if needed).
1691→func addCheckpointTrailer(message string, checkpointID id.CheckpointID) string {
1692→	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
1693→
1694→	// If message already ends with trailers (lines starting with key:), just append
1695→	// Otherwise, add a blank line first
1696→	lines := strings.Split(strings.TrimRight(message, "\n"), "\n")
1697→
1698→	// Check if the message already ends with a trailer paragraph.
1699→	// Git trailers must be in a separate paragraph (preceded by a blank line).
1700→	// A single-paragraph message (e.g., just a subject line) cannot have trailers,
1701→	// even if the subject contains ": " (like conventional commits: "docs: Add foo").
1702→	//
1703→	// Scan from the bottom: find the last paragraph of non-comment content,
1704→	// then check if it looks like trailers AND has a blank line above it.
1705→	hasTrailers := false
1706→	i := len(lines) - 1
1707→
1708→	// Skip trailing comment lines
1709→	for i >= 0 && strings.HasPrefix(strings.TrimSpace(lines[i]), "#") {
1710→		i--
1711→	}
1712→
1713→	// Check if the last non-comment line looks like a trailer
1714→	if i >= 0 {
1715→		line := strings.TrimSpace(lines[i])
1716→		if line != "" && strings.Contains(line, ": ") {
1717→			// Found a trailer-like line. Now scan upward past the trailer block
1718→			// to verify there's a blank line (paragraph separator) above it.
1719→			for i > 0 {
1720→				i--
1721→				above := strings.TrimSpace(lines[i])
1722→				if strings.HasPrefix(above, "#") {
1723→					continue
1724→				}
1725→				if above == "" {
1726→					// Blank line found above trailer block — real trailers
1727→					hasTrailers = true
1728→					break
1729→				}
1730→				if !strings.Contains(above, ": ") {
1731→					// Non-trailer, non-blank line — this is message body, not trailers
1732→					break
1733→				}
1734→				// Another trailer-like line, keep scanning upward
1735→			}
1736→		}
1737→	}
1738→
1739→	if hasTrailers {
1740→		// Append trailer directly
1741→		return strings.TrimRight(message, "\n") + "\n" + trailer + "\n"
1742→	}
1743→
1744→	// Add blank line before trailer
1745→	return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n"
1746→}
1747→
1748→// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer with an explanatory comment.
1749→// The trailer is placed above the git comment block but below the user's message area,
1750→// with a comment explaining that the user can remove it if they don't want to link the commit
1751→// to the agent session. If prompt is non-empty, it's shown as context.
1752→func addCheckpointTrailerWithComment(message string, checkpointID id.CheckpointID, agentName, prompt string) string {
1753→	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
1754→	commentLines := []string{
1755→		"# Remove the Entire-Checkpoint trailer above if you don't want to link this commit to " + agentName + " session context.",
1756→	}
1757→	if prompt != "" {
1758→		commentLines = append(commentLines, "# Last Prompt: "+prompt)
1759→	}
1760→	commentLines = append(commentLines, "# The trailer will be added to your next commit based on this branch.")
1761→	comment := strings.Join(commentLines, "\n")
1762→
1763→	lines := strings.Split(message, "\n")
1764→
1765→	// Find where the git comment block starts (first # line)
1766→	commentStart := -1
1767→	for i, line := range lines {
1768→		if strings.HasPrefix(line, "#") {
1769→			commentStart = i
1770→			break
1771→		}
1772→	}
1773→
1774→	if commentStart == -1 {
1775→		// No git comments, append trailer at the end
1776→		return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n" + comment + "\n"
1777→	}
1778→
1779→	// Split into user content and git comments
1780→	userContent := strings.Join(lines[:commentStart], "\n")
1781→	gitComments := strings.Join(lines[commentStart:], "\n")
1782→
1783→	// Build result: user content, blank line, trailer, comment, blank line, git comments
1784→	userContent = strings.TrimRight(userContent, "\n")
1785→	if userContent == "" {
1786→		// No user content yet - leave space for them to type, then trailer
1787→		// Two newlines: first for user's message line, second for blank separator
1788→		return "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
1789→	}
1790→	return userContent + "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
1791→}
