2352→// filesTouchedByCheckpointTrailer finds the commit with a given Entire-Checkpoint trailer
2353→// and returns the files changed in that commit. Used as a fallback when condensation failed
2354→// at commit time and needs to be retried at stop time.
2355→func filesTouchedByCheckpointTrailer(ctx context.Context, repoDir string, cpID string) []string {
2356→	if repoDir == "" {
2357→		return nil
2358→	}
2359→
2360→	// Find the commit with this checkpoint trailer.
2361→	out, err := exec.CommandContext(ctx, "git", "-C", repoDir,
2362→		"log", "--all", "--grep=Entire-Checkpoint: "+cpID, "--format=%H", "-1").Output()
2363→	if err != nil || len(bytes.TrimSpace(out)) == 0 {
2364→		return nil
2365→	}
2366→	hash := strings.TrimSpace(string(out))
2367→
2368→	// Get files changed in that commit.
2369→	filesOut, err := exec.CommandContext(ctx, "git", "-C", repoDir,
2370→		"diff-tree", "--no-commit-id", "--name-only", "-r", hash).Output()
2371→	if err != nil {
2372→		return nil
2373→	}
2374→
2375→	var files []string
2376→	for _, line := range strings.Split(strings.TrimSpace(string(filesOut)), "\n") {
2377→		if line != "" {
2378→			files = append(files, line)
2379→		}
2380→	}
2381→	return files
2382→}
