2384→// filesChangedInCommit returns the set of files changed in a commit using git diff-tree.
2385→// Uses the git CLI for faster performance vs go-git tree walks (lower constant factors).
2386→// Falls back to go-git tree walk if git diff-tree fails, since an empty result would
2387→// break downstream condensation and carry-forward logic.
2388→func filesChangedInCommit(ctx context.Context, repoDir string, commit *object.Commit, headTree, parentTree *object.Tree) map[string]struct{} {
2389→	var parentHash string
2390→	if commit.NumParents() > 0 {
2391→		parentHash = commit.ParentHashes[0].String()
2392→	}
2393→	result, err := gitops.DiffTreeFiles(ctx, repoDir, parentHash, commit.Hash.String())
2394→	if err != nil {
2395→		logging.Warn(ctx, "post-commit: git diff-tree failed, falling back to tree walk",
2396→			slog.String("commit", commit.Hash.String()),
2397→			slog.String("error", err.Error()),
2398→		)
2399→		return filesChangedInCommitFallback(ctx, headTree, parentTree)
2400→	}
2401→	return result
2402→}
