2404→// filesChangedInCommitFallback uses go-git tree walks to compute changed files.
2405→// Slower than git diff-tree but doesn't depend on an external process.
2406→func filesChangedInCommitFallback(ctx context.Context, headTree, parentTree *object.Tree) map[string]struct{} {
2407→	files, err := getAllChangedFilesBetweenTreesSlow(ctx, parentTree, headTree)
